+/// Drop repeated corners and corners on a straight run, until none is left.
+fn simplify(mut poly: Vec<(f64, f64)>) -> Vec<(f64, f64)> {
+    loop {
+        let n = poly.len();
+        if n < 3 {
+            return poly;
+        }
+        let drop = (0..n).find(|&i| {
+            let (a, b, c) = (poly[(i + n - 1) % n], poly[i], poly[(i + 1) % n]);
+            a == b || (b.0 - a.0) * (c.1 - a.1) - (b.1 - a.1) * (c.0 - a.0) == 0.0
+        });
+        match drop {
+            Some(i) => {
+                poly.remove(i);
+            }
+            None => return poly,
+        }
+    }
+}
