+            "the stock's centre is {off:.3} mm off the self-centering vise's centre along its jaws - the jaws clamp it centred; place the vise on the stock (Fit) first"
+        ));
+    }
+    let across = hi - lo;
+    in_range(p, sc, across)?;
+    Ok(across)
+}

